/**
 * 将测算引擎 + Demo Repository 打包为静态 Demo 可用的 IIFE。
 * 输出：demo-frontend-package/lib/pm-calc.bundle.js
 */
import * as esbuild from "esbuild";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const outfile = path.join(root, "demo-frontend-package/lib/pm-calc.bundle.js");

await esbuild.build({
  entryPoints: [path.join(root, "src/demo/browser-bridge.ts")],
  bundle: true,
  format: "iife",
  globalName: "PmCalcModule",
  platform: "browser",
  target: ["es2020"],
  outfile,
  sourcemap: true,
  minify: false,
  logLevel: "info",
  alias: {
    "@": path.join(root, "src"),
  },
  banner: {
    js: "/* PmCalc browser engine — generated by scripts/build-demo-calc-bundle.mjs; do not edit */",
  },
  footer: {
    js: "\nif (typeof window !== 'undefined' && window.PmCalcModule && window.PmCalcModule.PmCalc) { window.PmCalc = window.PmCalcModule.PmCalc; }\n",
  },
});

const serverOut = path.join(root, "demo-frontend-package/lib/document-import.server.mjs");
await esbuild.build({
  entryPoints: [path.join(root, "src/demo/import/real/node-entry.ts")],
  bundle: true,
  format: "esm",
  platform: "node",
  target: ["node20"],
  outfile: serverOut,
  sourcemap: true,
  minify: false,
  logLevel: "info",
  packages: "external",
  alias: {
    "@": path.join(root, "src"),
  },
  banner: {
    js: "/* document import server — generated; do not edit */",
  },
});

console.log(`built ${outfile}`);
console.log(`built ${serverOut}`);
